document.addEventListener("DOMContentLoaded",(function(){var e=new Map;$(document).on("select2:open",(function(t){if(!1!==t.target.classList.value.includes("expandOnFocus")){var i=t.target,n=$(i).next(".select2-container");if(n.length){if(!e.has(i.id)){var s=n.find(".select2-selection").outerHeight();e.set(i.id,s)}n.css({height:"auto","min-height":"75px"}),n.find(".select2-selection--multiple").css({height:"auto","min-height":"75px","max-height":"150","overflow-y":"auto"}),n.find(".select2-selection--single").css({height:"auto","min-height":"38px"})}}})),$(document).on("select2:close",(function(t){if(!1!==t.target.classList.value.includes("expandOnFocus")){var i=t.target,n=$(i).next(".select2-container");if(n.length){var s=e.get(i.id)||"38px";n.css({height:s,"min-height":""}),n.find(".select2-selection--multiple").css({height:s,"min-height":"","max-height":"","overflow-y":""}),n.find(".select2-selection--single").css({height:s,"min-height":""})}}}))}));
